		/** 
		 * Tests creating a new GiftCard.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a GiftCard");

			StringBuilder msg = new StringBuilder( "-- Failed to create a GiftCard" );

			try {            
				GiftCard entity = GiftCardService.getGiftCardInstance().createGiftCard( generateNewEntity() );
				thePrimaryKey = entity.getGiftCardId();
				LOGGER.info( "-- Successfully created a GiftCard with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a GiftCard. 
		 */
		public GiftCard testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created GiftCard" );

			GiftCard entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read GiftCard with primary key" );
			msg.append( thePrimaryKey );
			
			GiftCardFetchOneSummary fetchOneSummary = new GiftCardFetchOneSummary( thePrimaryKey );

			try {
				entity = GiftCardService.getGiftCardInstance().getGiftCard( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found GiftCard " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a GiftCard.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a GiftCard." );

			StringBuilder msg = new StringBuilder( "Failed to update a GiftCard : " );        
			GiftCard entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created GiftCard." );

				// for use later on...
				thePrimaryKey = entity.getGiftCardId();

				GiftCardService proxy = GiftCardService.getGiftCardInstance();            
				proxy.updateGiftCard( entity );   

				LOGGER.info( "-- Successfully saved GiftCard - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a GiftCard.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created GiftCard." );

			try{
			    GiftCard entity = testRead(); 
				GiftCardService.getGiftCardInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted GiftCard with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete GiftCard with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all GiftCards.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of GiftCards:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all GiftCard : " );        
			List<GiftCard> collection  = null;

			try {
				// call the static get method on the GiftCardService
				collection = GiftCardService.getGiftCardInstance().getAllGiftCard();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					GiftCard entity = null;            
					Iterator<GiftCard> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getGiftCardId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

